package luhn

import "testing"

func TestValid(t *testing.T) {
	tests := []struct {
		name   string
		number string
		want   bool
	}{
		// Валидные номера по алгоритму Луна
		{
			name:   "стандартный валидный номер",
			number: "49927398716",
			want:   true,
		},
		{
			name:   "валидный номер из 16 цифр",
			number: "1234567812345670",
			want:   true,
		},
		{
			name:   "валидный номер с чётным количеством цифр",
			number: "4532015112830366",
			want:   true,
		},
		{
			name:   "валидный номер из примера задания",
			number: "12345678903",
			want:   true,
		},
		{
			name:   "короткий валидный номер",
			number: "18",
			want:   true,
		},
		{
			name:   "валидный номер с нулями",
			number: "00000000000",
			want:   true,
		},

		// Невалидные номера
		{
			name:   "невалидный номер",
			number: "49927398717",
			want:   false,
		},
		{
			name:   "невалидный номер из 16 цифр",
			number: "1234567812345678",
			want:   false,
		},
		{
			name:   "невалидный короткий номер",
			number: "12",
			want:   false,
		},
		{
			name:   "невалидный номер с изменённой последней цифрой",
			number: "4532015112830367",
			want:   false,
		},

		// Граничные случаи
		{
			name:   "пустая строка",
			number: "",
			want:   false,
		},
		{
			name:   "одна цифра",
			number: "5",
			want:   false,
		},
		{
			name:   "строка с буквами",
			number: "49927398716a",
			want:   false,
		},
		{
			name:   "строка с пробелами",
			number: "49927 398716",
			want:   false,
		},
		{
			name:   "строка со спецсимволами",
			number: "49927-398716",
			want:   false,
		},
		{
			name:   "только буквы",
			number: "abcdef",
			want:   false,
		},
		{
			name:   "очень длинный валидный номер",
			number: "",
			want:   true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Valid(tt.number)
			if got != tt.want {
				t.Errorf("Valid(%q) = %v, want %v", tt.number, got, tt.want)
			}
		})
	}
}

func BenchmarkValid(b *testing.B) {
	number := "49927398716"
	b.ResetTimer()
	for b.Loop() {
		Valid(number)
	}
}
